when.condition:
@{
            var prefix = context.Subscription.Id == "research-team-sub" ? "research" : "engineering";
            var userId = context.Request.Headers.GetValueOrDefault("x-demo-user-id", "");
            return !System.Text.RegularExpressions.Regex.IsMatch(userId, "^" + prefix + "-user-[12]$");
          }

@{
            var token = (Jwt)context.Variables["validated-jwt"];
            var tid = token.Claims.GetValueOrDefault("tid", "");
            var oid = token.Claims.GetValueOrDefault("oid", "");
            return tid.ToLowerInvariant() != "{{tenant-id}}".ToLowerInvariant()
              || !System.Text.RegularExpressions.Regex.IsMatch(oid, "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$");
          }

set-variable.value:
@{
      var serviceId = context.Deployment.ServiceId ?? string.Empty;
      var markerIndex = serviceId.ToLowerInvariant().IndexOf("/providers/");
      return markerIndex > 0 ? serviceId.Substring(0, markerIndex) : string.Empty;
    }

@{
      var resourceGroupId = (string)context.Variables["resource-group-id"];
      var host = context.Api.ServiceUrl == null ? string.Empty : context.Api.ServiceUrl.Host;
      var dotIndex = host.IndexOf(".");
      var accountName = dotIndex > 0 ? host.Substring(0, dotIndex) : host;
      return string.IsNullOrEmpty(resourceGroupId) || string.IsNullOrEmpty(accountName)
        ? string.Empty
        : resourceGroupId + "/providers/Microsoft.CognitiveServices/accounts/" + accountName;
    }

@{
      var material = ((string)context.Variables["subject-tenant"]).ToLowerInvariant()
        + "|" + (string)context.Variables["subject-kind"]
        + "|" + ((string)context.Variables["subject-value"]).ToLowerInvariant();
      var key = Convert.FromBase64String("{{usage-hmac-key}}");
      var hmac = new System.Security.Cryptography.HMACSHA256(key);
      var digest = hmac.ComputeHash(System.Text.Encoding.UTF8.GetBytes(material));
      hmac.Dispose();
      return Convert.ToBase64String(digest).TrimEnd('=').Replace('+', '-').Replace('/', '_');
    }

inbound.set-body:
@{
      var body = context.Request.Body.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      body["model"] = "gpt-5.4";
      body["instructions"] = "If the user requests copyrighted content such as books, lyrics, recipes, news articles or other content that may violate copyrights or be considered as copyright infringement, politely refuse and explain that you cannot provide the content. Include a short description or summary of the work that the user is asking for. You must not violate any copyrights under any circumstances.";
      return body.ToString(Newtonsoft.Json.Formatting.None);
    }

outbound.log-to-eventhub:
@{
      Newtonsoft.Json.Linq.JObject payload = null;
      try
      {
        var responseText = context.Response.Body == null
          ? string.Empty
          : context.Response.Body.As<string>(preserveContent: true);
        if (!string.IsNullOrWhiteSpace(responseText))
        {
          payload = Newtonsoft.Json.Linq.JObject.Parse(responseText);
        }
      }
      catch (Exception)
      {
        payload = null;
      }

      var usage = payload == null ? null : payload["usage"] as Newtonsoft.Json.Linq.JObject;
      var inputValue = usage == null ? null : usage["input_tokens"];
      var outputValue = usage == null ? null : usage["output_tokens"];
      var totalValue = usage == null ? null : usage["total_tokens"];
      var inputDetails = usage == null ? null : usage["input_tokens_details"] as Newtonsoft.Json.Linq.JObject;
      var outputDetails = usage == null ? null : usage["output_tokens_details"] as Newtonsoft.Json.Linq.JObject;
      var cachedValue = inputDetails == null ? null : inputDetails["cached_tokens"];
      var reasoningValue = outputDetails == null ? null : outputDetails["reasoning_tokens"];

      long? inputTokens = inputValue != null && inputValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer
        ? (long?)Math.Max(0L, (long)inputValue)
        : null;
      long? cachedInputTokens = cachedValue != null && cachedValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer
        ? (long?)Math.Max(0L, (long)cachedValue)
        : null;
      long? uncachedInputTokens = inputTokens.HasValue && cachedInputTokens.HasValue
        ? (long?)Math.Max(inputTokens.Value - cachedInputTokens.Value, 0L)
        : null;
      long? outputTokens = outputValue != null && outputValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer
        ? (long?)Math.Max(0L, (long)outputValue)
        : null;
      long? reasoningTokens = reasoningValue != null && reasoningValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer
        ? (long?)Math.Max(0L, (long)reasoningValue)
        : null;
      long? visibleOutputTokens = outputTokens.HasValue && reasoningTokens.HasValue
        ? (long?)Math.Max(outputTokens.Value - reasoningTokens.Value, 0L)
        : null;
      long? totalTokens = totalValue != null && totalValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer
        ? (long?)Math.Max(0L, (long)totalValue)
        : inputTokens.HasValue && outputTokens.HasValue
          ? (long?)(inputTokens.Value + outputTokens.Value)
          : null;

      Newtonsoft.Json.Linq.JObject rawUsage = null;
      if (usage != null)
      {
        rawUsage = new Newtonsoft.Json.Linq.JObject();
        if (inputValue != null && inputValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer)
        {
          rawUsage["input_tokens"] = (long)inputValue;
        }
        if (outputValue != null && outputValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer)
        {
          rawUsage["output_tokens"] = (long)outputValue;
        }
        if (totalValue != null && totalValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer)
        {
          rawUsage["total_tokens"] = (long)totalValue;
        }
        var rawInputDetails = new Newtonsoft.Json.Linq.JObject();
        if (cachedValue != null && cachedValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer)
        {
          rawInputDetails["cached_tokens"] = (long)cachedValue;
        }
        if (rawInputDetails.Count > 0)
        {
          rawUsage["input_tokens_details"] = rawInputDetails;
        }
        var rawOutputDetails = new Newtonsoft.Json.Linq.JObject();
        if (reasoningValue != null && reasoningValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer)
        {
          rawOutputDetails["reasoning_tokens"] = (long)reasoningValue;
        }
        if (rawOutputDetails.Count > 0)
        {
          rawUsage["output_tokens_details"] = rawOutputDetails;
        }
        if (rawUsage.Count == 0)
        {
          rawUsage = null;
        }
      }

      var responseId = payload != null && payload["id"] != null
        && payload["id"].Type == Newtonsoft.Json.Linq.JTokenType.String
        ? (string)payload["id"]
        : string.Empty;
      if (responseId.Length > 256)
      {
        responseId = responseId.Substring(0, 256);
      }
      var responseModel = payload != null && payload["model"] != null
        && payload["model"].Type == Newtonsoft.Json.Linq.JTokenType.String
        ? (string)payload["model"]
        : string.Empty;
      if (!System.Text.RegularExpressions.Regex.IsMatch(responseModel, "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$"))
      {
        responseModel = string.Empty;
      }

      var traceParent = context.Request.Headers.GetValueOrDefault("traceparent", string.Empty);
      var traceMatch = System.Text.RegularExpressions.Regex.Match(
        traceParent,
        "^[0-9A-Fa-f]{2}-([0-9A-Fa-f]{32})-[0-9A-Fa-f]{16}-[0-9A-Fa-f]{2}$");
      var traceId = traceMatch.Success ? traceMatch.Groups[1].Value.ToLowerInvariant() : string.Empty;
      var eventKey = context.RequestId.ToString("D") + "|OpenAI|" + responseId + "|" + responseModel;
      var sha = System.Security.Cryptography.SHA256.Create();
      var eventDigest = sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(eventKey));
      sha.Dispose();
      var eventId = Convert.ToBase64String(eventDigest).TrimEnd('=').Replace('+', '-').Replace('/', '_');
      var statusCode = context.Response.StatusCode;
      var requestOutcome = statusCode >= 200 && statusCode <= 299
        ? (payload == null ? "unavailable" : "succeeded")
        : "failed";
      var tokenQuality = rawUsage == null
        ? "missing"
        : inputTokens.HasValue
          && cachedInputTokens.HasValue
          && outputTokens.HasValue
          && reasoningTokens.HasValue
          && totalValue != null
          && totalValue.Type == Newtonsoft.Json.Linq.JTokenType.Integer
            ? "exact"
            : "partial";

      var usageEvent = new Newtonsoft.Json.Linq.JObject();
      usageEvent["schemaVersion"] = "1.0";
      usageEvent["eventTimeUtc"] = DateTime.UtcNow.ToString("o");
      usageEvent["eventId"] = eventId;
      usageEvent["correlationId"] = context.RequestId.ToString("D");
      usageEvent["traceId"] = string.IsNullOrEmpty(traceId)
        ? (Newtonsoft.Json.Linq.JToken)Newtonsoft.Json.Linq.JValue.CreateNull()
        : new Newtonsoft.Json.Linq.JValue(traceId);
      usageEvent["provider"] = "OpenAI";
      usageEvent["requestModel"] = "gpt-5.4";
      usageEvent["responseModel"] = string.IsNullOrEmpty(responseModel)
        ? (Newtonsoft.Json.Linq.JToken)Newtonsoft.Json.Linq.JValue.CreateNull()
        : new Newtonsoft.Json.Linq.JValue(responseModel);
      usageEvent["deploymentName"] = "gpt-5.4";
      usageEvent["deploymentType"] = "GlobalStandard";
      usageEvent["modelResourceId"] = (string)context.Variables["model-resource-id"];
      usageEvent["resourceGroupId"] = (string)context.Variables["resource-group-id"];
      usageEvent["teamId"] = (string)context.Variables["attribution-team"];
      usageEvent["subjectId"] = (string)context.Variables["subject-id"];
      usageEvent["projectId"] = "platform-engineering";
      usageEvent["attributionMode"] = (string)context.Variables["attribution-mode"];
      usageEvent["requestOutcome"] = requestOutcome;
      usageEvent["httpStatusCode"] = statusCode;
      usageEvent["latencyMs"] = Math.Max(0L, (long)context.Elapsed.TotalMilliseconds);
      usageEvent["tokenQuality"] = tokenQuality;
      usageEvent["inputTokens"] = inputTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(inputTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["cachedInputTokens"] = cachedInputTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(cachedInputTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["uncachedInputTokens"] = uncachedInputTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(uncachedInputTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["cacheWrite5mTokens"] = Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["cacheWrite1hTokens"] = Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["outputTokens"] = outputTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(outputTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["reasoningTokens"] = reasoningTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(reasoningTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["visibleOutputTokens"] = visibleOutputTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(visibleOutputTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["totalTokens"] = totalTokens.HasValue
        ? new Newtonsoft.Json.Linq.JValue(totalTokens.Value)
        : Newtonsoft.Json.Linq.JValue.CreateNull();
      usageEvent["rawUsage"] = rawUsage == null
        ? (Newtonsoft.Json.Linq.JToken)Newtonsoft.Json.Linq.JValue.CreateNull()
        : rawUsage;
      return usageEvent.ToString(Newtonsoft.Json.Formatting.None);
    }

